package com.mantou.salesdialer.contacts;
import java.time.*;import java.util.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
public final class LocalPlanCheck {
 static int checks;static void eq(Object a,Object b){checks++;if(!Objects.equals(a,b))throw new AssertionError("LOCAL_PLAN_ASSERTION_"+checks);}static void fail(Runnable r,String msg){checks++;try{r.run();}catch(RuntimeException e){if(msg.equals(e.getMessage()))return;throw new AssertionError(e);}throw new AssertionError("EXPECTED_"+msg);}
 public static void main(String[] args){String slot="a".repeat(32);var s=LocalDraftBinding.snapshot(DataClass.FORMAT_FIXTURE,slot,"LOCAL-TARGET-"+"b".repeat(32),1,Qualification.CONFIRMED,false,"GENERATED");var d=LocalDraftBinding.create(s);var a=LocalDraftBinding.actor(s.dataClass,s.slot);var c=LocalDraftBinding.contact(s);var t=LocalDraftBinding.task(d);long due=Instant.parse("2026-10-19T01:10:00Z").toEpochMilli();var initial=SalesPlanModel.initial(a);var p=SalesPlanModel.arrange(a,initial,t,c,0,1,1,due,due-60000);eq(p.version,1L);eq(p.paused,false);eq(p.contactRevision,1L);eq(p.taskId,d.id);eq(d.realCallsEnabled,false);for(int i=0;i<4;i++)eq(SalesPlanModel.status(a,p,t,c,1,due+new long[]{-1,0,30000,30001}[i]),new String[]{"NOT_DUE","DUE_METADATA_ONLY","DUE_METADATA_ONLY","EXPIRED"}[i]);System.out.println("T683 local typed draft uses existing weekday/version/30-second plan rules passed");
 fail(()->SalesPlanModel.arrange(a,p,t,c,0,1,1,due,due-60000),"STALE_PLAN");fail(()->SalesPlanModel.arrange(a,p,t,c,1,2,1,due,due-60000),"STALE_CONTACT");fail(()->SalesPlanModel.arrange(a,p,t,c,1,1,2,due,due-60000),"STALE_DRAFT");fail(()->SalesPlanModel.arrange(a,p,t,c,1,1,1,due-2,due),"PAST_DUE");fail(()->SalesPlanModel.arrange(a,p,t,c,1,1,1,Instant.parse("2026-10-19T10:00:00Z").toEpochMilli(),due),"OUTSIDE_WINDOW");var other=LocalDraftBinding.actor(DataClass.LOCAL_PHONE_INTAKE,slot);fail(()->SalesPlanModel.stop(other,p,1),"FORBIDDEN");var changed=LocalDraftBinding.snapshot(s.dataClass,slot,s.targetId,2,Qualification.WITHDRAWN,false,"GENERATED");eq(SalesPlanModel.status(a,p,t,LocalDraftBinding.contact(changed),1,due),"STALE_CONTACT");System.out.println("T684 stale plan/contact/draft, past time, wrong scope and withdrawal stop metadata authorization passed");
 var paused=SalesPlanModel.stop(a,p,1);eq(paused.version,2L);eq(paused.paused,true);eq(paused.taskId,"");eq(SalesPlanModel.stop(a,paused,2),paused);eq(SalesPlanModel.status(a,paused,t,c,2,due),"PAUSED");eq(SalesPlanModel.status(a,paused,t,c,1,due),"STALE_PLAN");System.out.println("T685 stop is idempotent and invalidates old plan without implicit resume passed");System.out.println("PASS: "+checks+" assertions; 3 local-plan scenarios; existing rules reused, no telephone");}
}
